    20		img   imagesearch.Image
    21		label string
    22	}
    23	
    24	// searchColumns describes the level 1 table. Minimal for now: the full screen
    25	// (Stars, Official, Description) comes later.
    26	func searchColumns() []datatable.Column[searchRow] {
    27		return []datatable.Column[searchRow]{
    28			datatable.IndicatorColumn(
    29				func(searchRow) indicator.State { return indicator.Idle },
    30				func(searchRow) string { return theme.IconDocker },
    31				func(searchRow) lipgloss.Style { return theme.IconStyle(theme.IconRoleImage) },
    32			),
    33			{
    34				Title: "Name", Sizing: datatable.SizingContent, MinWidth: 24, Flex: 1,
    35				Cell:   func(r searchRow) string { return r.img.Name },
    36				Search: func(r searchRow) string { return r.img.Name },
    37			},
    38			{
    39				Title: "Registry", Sizing: datatable.SizingContent, MinWidth: 16,
    40				Cell: func(r searchRow) string { return r.label },
    41			},
    42		}
    43	}
    44	
    45	// newSearchTable builds the level 1 table, in arrival order (no sort).
    46	func newSearchTable() *datatable.Model[searchRow] {
    47		t := datatable.New(datatable.Config[searchRow]{
    48			Columns:    searchColumns(),
    49			SortColumn: -1,
    50		})
    51		return &t
    52	}
    53	
    54	// rebuildSearchTable hands the collected images to the table.
    55	func (b *RegistryBrowser) rebuildSearchTable() {
    56		rows := make([]searchRow, len(b.images))
    57		for i, img := range b.images {
    58			label := ""
    59			if e := b.entryFor(img.EntryKey); e != nil {
    60				label = entryAlias(*e)
    61				if label == "" {
    62					label = e.URL
    63				}
    64			}
    65			rows[i] = searchRow{img: img, label: label}
    66		}
    67		b.searchTable.SetItems(rows)
    68		b.resizeTables()
    69	}
    70	
    71	// AddImageResults takes one registry's answer. It returns false, touching
    72	// nothing, when the answer belongs to another lot. pendingSearches never goes
    73	// below zero.
    74	func (b *RegistryBrowser) AddImageResults(msg ImageSearchResultMsg) bool {
    75		if msg.Gen != b.gen {
    76			return false
    77		}
    78		if b.pendingSearches > 0 {
    79			b.pendingSearches--
    80		}
    81		if msg.Err == nil {
    82			for _, img := range msg.Images {
    83				img.EntryKey = msg.EntryKey
    84				b.images = append(b.images, img)
    85			}
    86		}
    87		b.rebuildSearchTable()
    88		return true
    89	}
    90	
    91	// handleImagesKeyMsg handles the keys of the level 1 table. esc closes the
    92	// filter bar first, then a confirmed query, then goes back to the form (which keeps the typed name and the
    93	// selection), and its late answers are no longer wanted: the lot is dropped
    94	// (TestEscAtLevelOneCancelsTheLotAndIgnoresItsLateAnswers). enter does nothing: a row has no action yet.
    95	func (b *RegistryBrowser) handleImagesKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
    96		if b.searchTable.InEditMode() {
    97			return b, b.searchTable.Update(msg)
    98		}
    99		switch msg.String() {
   100		case "esc":
   101			if bar := b.searchTable.FilterBar(); bar.SearchQuery() != "" {
   102				bar.ClearSearch()
   103				b.searchTable.SetItems(b.searchTable.Items())
   104				return b, nil
   105			}
   106			b.cancelInFlight()
   107			b.gen = nextBrowserGen()
   108			b.pendingSearches = 0
   109			b.state = browserStateInput
   110			b.searchTable.Blur()
   111			b.updateFocus()
   112			return b, nil
   113		case "enter":
   114			return b, nil
   115		}
   116		return b, b.searchTable.Update(msg)
   117	}
   118	
   119	// handleImageSearchResult records one registry's answer; a stale one is ignored.
   120	func (m Model) handleImageSearchResult(msg ImageSearchResultMsg) (tea.Model, tea.Cmd) {
   121		if m.registryBrowser == nil || !m.registryBrowser.AddImageResults(msg) {
   122			return m, nil
   123		}
   124		if msg.Err != nil {
   125			alias := msg.EntryKey
   126			if e := m.registryBrowser.entryFor(msg.EntryKey); e != nil {
   127				alias = entryAlias(*e)
   128			}
   129			log.Printf("ERROR [oci_resources] image search on %s: %s", alias, jobs.SafeCause(msg.Err))
   130		}
   131		return m, nil
   132	}
   133	
   134	// handleRegistryBrowserWarn shows the browser's warning in the footer.
   135	func (m Model) handleRegistryBrowserWarn(msg RegistryBrowserWarnMsg) (tea.Model, tea.Cmd) {
   136		return m, m.footer.Warn(strings.TrimSpace(msg.Text))
   137	}
